(()=>{'use strict';const button=document.getElementById('run-connected-system'),box=document.getElementById('connected-run-results');function show(text){const p=document.createElement('p');p.textContent=text;box.append(p);}try{const previous=JSON.parse(sessionStorage.getItem('zuxuru-connected-run'));if(Array.isArray(previous)){previous.forEach(show);sessionStorage.removeItem('zuxuru-connected-run');}}catch{}button.onclick=async()=>{button.disabled=true;box.replaceChildren();let release;try{release=window.bongaRunGate.begin();const r=await fetch('/api/system/run',{method:'POST'}),data=await r.json();if(!r.ok){if(data.id)document.dispatchEvent(new CustomEvent('designer-cloud-changed'));throw Error(data.error||'System run failed.');}const lines=[data.status,...data.steps.map(s=>s.name+': '+s.status+(s.message?' · '+s.message:'')+(s.tasksAdded!==undefined?' · '+s.tasksAdded+' proposed tasks':'')),data.notice];lines.forEach(show);document.dispatchEvent(new CustomEvent('designer-cloud-changed'));let kept=false;try{sessionStorage.setItem('zuxuru-connected-run',JSON.stringify(lines));kept=true;}catch{}if(kept){location.hash='#overview';location.reload();}else{show('Run report saved in your account. Reload the workspace to see updated records, then use Recent system runs to review this report.');const reload=document.createElement('button');reload.type='button';reload.textContent='Reload saved workspace';reload.onclick=()=>location.reload();box.append(reload);}}catch(e){show(e.message+' Reload saved records before retrying.');button.disabled=false;}finally{release?.();}};const history=document.getElementById('refresh-connected-history');if(history)history.onclick=async()=>{history.disabled=true;box.replaceChildren();show('Loading your saved system runs…');try{const response=await fetch('/api/system/run'),data=await response.json();if(!response.ok)throw Error(data.error||'System history unavailable.');box.replaceChildren();if(!data.runs.length)show('No system runs saved yet.');for(const run of data.runs){show(new Date(run.createdAt).toLocaleString()+' · '+run.status);for(const step of run.steps||[])show(step.name+': '+step.status+(step.message?' · '+step.message:''));if(run.notice)show(run.notice);}}catch(e){box.replaceChildren();show(e.message||'System history unavailable.');}finally{history.disabled=false;}};
})();
